examples.code:
x = [3 5 2 8 7 6 9 4];
y = [2 3 4 5 5 3 6 2];
[p, h, s] = signtest(x, y);
fprintf('p = %.4f, h = %d, sign = %d\n', p, h, s.sign)

x = [3 5 2 8 7 6 9 4];
y = [2 3 4 5 5 3 6 2];
[p, h, s] = signtest(x, y, 'method', 'approximate', 'tail', 'right');
fprintf('p = %.4f, z = %.4f\n', p, s.zval)

a = [4.1 5.2 3.8 6.0 5.5 4.7 5.9 4.4];
[h, p, ci, st] = vartest(a, 1);
fprintf('h = %d, p = %.4f, chi2 = %.4f, df = %d\n', h, p, st.chisqstat, st.df)
fprintf('ci = [%.4f %.4f]\n', ci)

A = [1 2; 3 4; 5 6];
[d, idx] = datasample(A, 2);
disp(size(d))
disp(isequal(d, A(idx, :)))

x = [2 4 6 8 10 15];
j = jackknife(@(z) [mean(z) var(z)], x);
disp(size(j))
disp(j(1, :))

x = (1:8)';
yb = [0 0 0 1 0 1 1 1]';
m = fitglm(x, yb, 'Distribution', 'binomial');
fprintf('%.4f\n', m.Coefficients.Estimate)
fprintf('deviance %.4f\n', m.Deviance)
disp(round(predict(m, [2; 7]) * 10000) / 10000)

x = (1:8)';
yc = [1 0 2 1 3 2 4 3]';
m = fitglm(x, yc, 'Distribution', 'poisson');
fprintf('%.4f\n', m.Coefficients.Estimate)
disp(m.Link.Name)

x = (1:8)';
yb = [0 0 0 1 0 1 1 1]';
m = fitglm(x, yb, 'Distribution', 'binomial');
p = glmval(m.Coefficients.Estimate, [2; 7], 'logit');
disp(round(p * 10000) / 10000)

x = (1:8)';
y = [2.1 3.9 6.2 7.8 10.1 12.2 13.8 16.1]';
m = fitlm(x, y);
fprintf('intercept %.4f, slope %.4f\n', m.Coefficients.Estimate)
fprintf('R2 %.4f, RMSE %.4f\n', m.Rsquared.Ordinary, m.RMSE)

b = [1; 2];
C = [1 0.2; 0.2 2];
[p, t, r] = linhyptest(b, C, 0, [1 -1]);
fprintf('p = %.4f, chi2 = %.4f, rank = %d\n', p, t, r)

x = (1:8)';
y = [2.1 3.9 6.2 7.8 10.1 12.2 13.8 16.1]';
m = fitlm(x, y);
[p, t, r] = linhyptest(m.Coefficients.Estimate, m.CoefficientCovariance, [0; 2], eye(2), m.DFE);
fprintf('p = %.4f, F = %.4f, rank = %d\n', p, t, r)

x = (1:8)';
h = leverage(x);
disp(round(h' * 10000) / 10000)
fprintf('sum %.4f\n', sum(h))

x = (1:8)';
h = leverage(x, 'quadratic');
disp(round(h' * 10000) / 10000)
fprintf('sum %.4f\n', sum(h))

o = statset('TolX', 1e-3, 'MaxIter', 50);
o2 = statset(o, 'Display', 'iter');
fprintf('%g %d %s\n', o2.TolX, o2.MaxIter, o2.Display)
